const req = $('Dashboard: operations action').first().json.body || {};
const p = req.params || {};
const who = $('Verify caller').first().json;
const role = who.role;
const actor = 'dashboard:' + who.userId;
const senior = ['admin', 'manager'].includes(role);
const planner = ['admin', 'manager', 'production'].includes(role);
const floor = ['admin', 'manager', 'production', 'warehouse'].includes(role);
const bad = (error, code = 400) => [{ json: { valid: false, code, error } }];
const ok = (rpc, body, note) => [{ json: { valid: true, rpc, body, note } }];
const s = (v) => String(v == null ? '' : v).trim();
switch (req.action) {
  case 'hold':
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_ov_hold_order', { p_order: p.order_id, p_reason: s(p.reason), p_actor: actor }, 'Order put on hold. Re-plan production to take it out of the schedule.');
  case 'release':
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_ov_release_order', { p_order: p.order_id, p_note: s(p.reason), p_actor: actor }, 'Hold lifted. Re-plan production to bring the order back into the schedule.');
  case 'priority':
    if (!senior) return bad('Only a manager or admin can change an order\'s priority.', 403);
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_ov_set_priority', { p_order: p.order_id, p_priority: Number(p.priority), p_reason: s(p.reason), p_actor: actor }, 'Priority changed. Re-plan production to apply it.');
  case 'review_changes':
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_oc_review_order', { p_order: p.order_id, p_status: s(p.status), p_note: s(p.reason), p_actor: actor }, 'Changes recorded as dealt with.');
  case 'courier_event':
    if (!s(p.code)) return bad('Choose a consignment.');
    return ok('flow_cr_record_event', { p_movement: s(p.code), p_event: s(p.event), p_direction: s(p.direction) || 'outbound', p_note: s(p.note), p_actor: actor }, 'Courier event recorded.');
  case 'claim_open':
    if (!senior) return bad('Only a manager or admin can open a courier claim.', 403);
    if (!s(p.code)) return bad('Choose a consignment.');
    return ok('flow_cr_open_claim', { p_movement: s(p.code), p_kind: s(p.kind), p_value: Number(p.value), p_note: s(p.note), p_actor: actor }, 'Claim recorded. Submit it to the courier yourself, then mark it submitted.');
  case 'claim_update':
    if (!senior) return bad('Only a manager or admin can update a courier claim.', 403);
    if (!s(p.claim)) return bad('Choose a claim.');
    return ok('flow_cr_claim_update', { p_claim: s(p.claim), p_status: s(p.status), p_recovered: p.recovered == null ? null : Number(p.recovered), p_note: s(p.note), p_actor: actor }, 'Claim updated.');
  case 'assign_operator':
    if (!planner) return bad('Only a manager, admin or production planner can assign operators.', 403);
    if (!p.order_id || !s(p.method)) return bad('Choose a job.');
    return ok('flow_js_set_operator', { p_order: p.order_id, p_method: s(p.method), p_operator: p.operator_id || null, p_actor: actor }, 'Operator saved.');
  case 'assign_job':
    if (!planner) return bad('Only a manager, admin or production planner can assign jobs.', 403);
    if (!p.order_id || !s(p.method)) return bad('Choose a job.');
    return ok('flow_js_assign', { p_order: p.order_id, p_method: s(p.method), p_operator: p.operator_id || null, p_recommended: p.recommended_id || null, p_reason: s(p.reason), p_actor: actor }, 'Assignment saved.');
  case 'assign_machine':
    if (!planner) return bad('Only a manager, admin or production planner can choose a machine for a job.', 403);
    if (!p.order_id || !s(p.method)) return bad('Choose a job.');
    return ok('flow_js_set_machine', { p_order: p.order_id, p_method: s(p.method), p_machine: p.machine_id || null, p_reason: s(p.reason), p_actor: actor }, 'Machine choice saved. Re-plan production to apply it.');
  case 'worker_save':
    if (!senior) return bad('Only a manager or admin can add or change workers.', 403);
    return ok('flow_wk_save', { p_id: p.id || null, p_name: s(p.name), p_history_name: s(p.history_name), p_active: typeof p.active === 'boolean' ? p.active : null, p_actor: actor }, 'Worker saved.');
  case 'worker_skill':
    if (!senior) return bad('Only a manager or admin can change what a worker can run.', 403);
    if (!p.operator_id || !s(p.kind) || !s(p.ref)) return bad('Choose a worker and a skill.');
    return ok('flow_wk_skill_set', { p_op: p.operator_id, p_kind: s(p.kind), p_ref: s(p.ref), p_level: Number(p.level), p_actor: actor }, 'Skill saved.');
  case 'worker_skill_clear':
    if (!senior) return bad('Only a manager or admin can change what a worker can run.', 403);
    if (!p.operator_id || !s(p.kind) || !s(p.ref)) return bad('Choose a worker and a skill.');
    return ok('flow_wk_skill_clear', { p_op: p.operator_id, p_kind: s(p.kind), p_ref: s(p.ref), p_actor: actor }, 'Skill removed.');
  case 'worker_shift':
    if (!senior) return bad('Only a manager or admin can change shifts.', 403);
    if (!p.operator_id) return bad('Choose a worker.');
    return ok('flow_wk_shift_set', { p_op: p.operator_id, p_weekday: Number(p.weekday), p_start: s(p.start) || null, p_end: s(p.end) || null, p_actor: actor }, 'Shift saved.');
  case 'worker_absence':
    if (!planner) return bad('Only a manager, admin or production planner can record time away.', 403);
    if (!p.operator_id) return bad('Choose a worker.');
    return ok('flow_wk_absence_add', { p_op: p.operator_id, p_from: s(p.from), p_to: s(p.to), p_reason: s(p.reason), p_actor: actor }, 'Time away recorded. Check their jobs on those days.');
  case 'worker_absence_remove':
    if (!planner) return bad('Only a manager, admin or production planner can change time away.', 403);
    if (!p.id) return bad('Choose an entry.');
    return ok('flow_wk_absence_remove', { p_id: p.id, p_actor: actor }, 'Removed.');
  case 'floor_start':
    if (!floor) return bad('Your role cannot start jobs.', 403);
    if (!p.step_id || !p.operator_id) return bad('Choose a job and a worker.');
    return ok('flow_fl_start', { p_step: p.step_id, p_operator: p.operator_id, p_actor: actor }, 'Job started.');
  case 'floor_stop':
    if (!floor) return bad('Your role cannot stop jobs.', 403);
    if (!p.step_id) return bad('Choose a job.');
    return ok('flow_fl_stop', { p_step: p.step_id, p_units: p.units == null || p.units === '' ? null : Number(p.units), p_finished: p.finished === true, p_note: s(p.note), p_actor: actor }, p.finished === true ? 'Job finished.' : 'Job stopped for now.');
  case 'set_switch':
    if (role !== 'admin') return bad('Only an admin can change the in-house production switches.', 403);
    if (!s(p.key) || typeof p.enabled !== 'boolean') return bad('Choose a switch and on or off.');
    return ok('flow_sc_set_switch', { p_key: s(p.key), p_enabled: p.enabled, p_reason: s(p.reason), p_actor: actor }, 'Switch changed. Re-plan production to apply it.');
  case 'set_scope':
    if (!senior) return bad('Only a manager or admin can change an order\'s scope.', 403);
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_sc_set_order_scope', { p_order: p.order_id, p_scope: p.scope || null, p_reason: s(p.reason), p_actor: actor }, 'Order scope changed. Re-plan production to apply it.');
  case 'portal_add_user':
    if (!senior) return bad('Only a manager or admin can invite decorator logins.', 403);
    if (!p.producer_id || !s(p.email)) return bad('Choose a decorator and enter an email.');
    return ok('flow_pp_add_user', { p_producer: p.producer_id, p_email: s(p.email), p_name: s(p.name), p_actor: actor }, 'Access given. They sign in at the portal with that email.');
  case 'portal_allow_email':
    if (role !== 'admin') return bad('Only an admin can allow a personal email address for the decorator portal.', 403);
    if (!s(p.email)) return bad('Enter the email address.');
    return ok('flow_portal_allow_email', { p_email: s(p.email), p_reason: s(p.reason), p_actor: actor }, 'Personal address allowed.');
  case 'portal_set_user':
    if (!senior) return bad('Only a manager or admin can switch decorator logins on or off.', 403);
    if (!p.user_id || typeof p.active !== 'boolean') return bad('Choose a person.');
    return ok('flow_pp_set_user_active', { p_user: p.user_id, p_active: p.active, p_reason: s(p.reason), p_actor: actor }, p.active ? 'Switched on.' : 'Switched off. They are signed out of the portal.');
  case 'portal_reply':
    if (!floor) return bad('Your role cannot reply to decorators.', 403);
    if (!s(p.code)) return bad('Choose a consignment.');
    return ok('flow_pp_reply', { p_movement: s(p.code), p_body: s(p.body), p_actor: actor }, 'Reply sent.');
  case 'portal_resolve':
    if (!floor) return bad('Your role cannot close a goods-in problem.', 403);
    if (!s(p.code)) return bad('Choose a consignment.');
    return ok('flow_pp_resolve_receipt', { p_movement: s(p.code), p_note: s(p.reason), p_actor: actor }, 'Goods-in problem marked as dealt with. The decorator has been told.');
  case 'waste_record': {
    if (!floor) return bad('Your role cannot record waste.', 403);
    const rec = { stage: s(p.stage), cause: s(p.cause), party: s(p.party) || null, qty: Number(p.qty), sku: s(p.sku) || null, product_name: s(p.product_name) || null, order_ref: s(p.order_ref) || null, producer_code: s(p.producer_code) || null, movement_code: s(p.movement_code) || null, machine_code: s(p.machine_code) || null, operator_name: s(p.operator_name) || null, reason: s(p.reason), replacement: p.replacement === true };
    return ok('flow_waste_record', { p: rec, p_actor: actor }, 'Waste recorded.');
  }
  case 'waste_confirm':
    if (!floor) return bad('Your role cannot confirm waste.', 403);
    if (!s(p.ref) || typeof p.confirm !== 'boolean') return bad('Choose a waste record.');
    return ok('flow_waste_confirm', { p_ref: s(p.ref), p_confirm: p.confirm, p_note: s(p.reason), p_actor: actor }, p.confirm ? 'Confirmed as waste.' : 'Dismissed.');
  case 'waste_decide':
    if (!senior) return bad('Only a manager or admin can approve waste.', 403);
    if (!s(p.ref) || typeof p.approve !== 'boolean') return bad('Choose a waste record.');
    return ok('flow_waste_decide', { p_ref: s(p.ref), p_approve: p.approve, p_note: s(p.reason), p_actor: actor }, p.approve ? 'Waste approved.' : 'Waste rejected.');
  case 'waste_recover':
    if (!senior) return bad('Only a manager or admin can record a recovery.', 403);
    if (!s(p.ref)) return bad('Choose a waste record.');
    return ok('flow_waste_recover', { p_ref: s(p.ref), p_amount: Number(p.amount), p_claim: s(p.claim) || null, p_note: s(p.reason), p_actor: actor }, 'Recovery recorded.');
  case 'waste_replacement':
    if (!planner) return bad('Only a manager, admin or production planner can ask for a replacement.', 403);
    if (!s(p.ref)) return bad('Choose a waste record.');
    return ok('flow_waste_replacement', { p_ref: s(p.ref), p_actor: actor }, 'Replacement requested. It is flagged on the order.');
  case 'waste_suggest':
    if (!floor) return bad('Your role cannot do that.', 403);
    return ok('flow_waste_suggest', {}, 'Checked quality, goods-in and courier records for waste.');
  case 'dispatch_pack':
    if (!floor) return bad('Your role cannot pack orders for dispatch.', 403);
    if (!p.order_id) return bad('Choose an order.');
    if (s(p.override) && !senior) return bad('Only a manager or admin can send an order that is not ready.', 403);
    return ok('flow_dispatch_pack', { p_order: p.order_id, p_parcels: Number(p.parcels), p_weights: Array.isArray(p.weights) && p.weights.length ? p.weights.map(Number) : null, p_carrier: s(p.carrier) || null, p_service: s(p.service) || null, p_note: s(p.note) || null, p_override: s(p.override) || null, p_actor: actor }, 'Packed. Print the labels next.');
  case 'dispatch_printed':
    if (!floor) return bad('Your role cannot record printing.', 403);
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_dispatch_printed', { p_order: p.order_id, p_reason: s(p.reason) || null, p_actor: actor }, 'Recorded as printed.');
  case 'dispatch_tracking':
    if (!floor) return bad('Your role cannot add tracking.', 403);
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_dispatch_set_tracking', { p_order: p.order_id, p_carrier: s(p.carrier) || null, p_tracking: s(p.tracking), p_parcel_no: p.parcel_no == null ? null : Number(p.parcel_no), p_actor: actor }, 'Tracking saved.');
  case 'dispatch_handover':
    if (!floor) return bad('Your role cannot hand parcels to the courier.', 403);
    if (!s(p.label)) return bad('Scan or enter a parcel label.');
    if (s(p.override) && !senior) return bad('Only a manager or admin can hand over a parcel that is no longer clear to go.', 403);
    return ok('flow_dispatch_handover', { p_label: s(p.label), p_override: s(p.override) || null, p_actor: actor }, 'Parcel handed over.');
  case 'dispatch_cancel':
    if (!floor) return bad('Your role cannot cancel packing.', 403);
    if (!p.order_id) return bad('Choose an order.');
    return ok('flow_dispatch_cancel', { p_order: p.order_id, p_reason: s(p.reason), p_actor: actor }, 'Packing cancelled.');
  case 'proof_create':
    if (!planner) return bad('Only a manager, admin or production planner can make customer proofs.', 403);
    if (!p.order_id || !Array.isArray(p.artwork_ids) || !p.artwork_ids.length) return bad('Choose the order and the areas on the proof.');
    return ok('flow_proof_create', { p_order: p.order_id, p_artwork_ids: p.artwork_ids, p_storage_path: s(p.storage_path), p_file_name: s(p.file_name), p_note: s(p.note) || null, p_actor: actor }, 'Proof saved as a draft.');
  case 'proof_send':
    if (!planner) return bad('Only a manager, admin or production planner can record a proof as sent.', 403);
    if (!p.proof_id) return bad('Choose a proof.');
    return ok('flow_proof_send', { p_proof: p.proof_id, p_to: s(p.to), p_via: s(p.via), p_note: s(p.note) || null, p_actor: actor }, 'Recorded as sent.');
  case 'proof_respond':
    if (!planner) return bad('Only a manager, admin or production planner can record the customer\'s answer.', 403);
    if (!p.proof_id) return bad('Choose a proof.');
    return ok('flow_proof_respond', { p_proof: p.proof_id, p_outcome: s(p.outcome), p_by: s(p.by), p_note: s(p.note) || null, p_evidence: s(p.evidence) || null, p_actor: actor }, 'Answer recorded.');
  case 'proof_withdraw':
    if (!planner) return bad('Only a manager, admin or production planner can withdraw a proof.', 403);
    if (!p.proof_id) return bad('Choose a proof.');
    return ok('flow_proof_withdraw', { p_proof: p.proof_id, p_reason: s(p.reason), p_actor: actor }, 'Proof withdrawn.');
  case 'stocktake_start':
    if (!floor) return bad('Your role cannot start a stock-take.', 403);
    return ok('flow_stocktake_start', { p_name: s(p.name), p_scope: p.scope && typeof p.scope === 'object' ? p.scope : {}, p_actor: actor }, 'Stock-take started.');
  case 'stocktake_count':
    if (!floor) return bad('Your role cannot enter stock counts.', 403);
    if (!p.take_id || !s(p.sku)) return bad('Choose a stock-take and a SKU.');
    return ok('flow_stocktake_count', { p_take: p.take_id, p_sku: s(p.sku), p_qty: p.qty == null || p.qty === '' ? null : Number(p.qty), p_actor: actor }, 'Count saved.');
  case 'stocktake_review':
    if (!floor) return bad('Your role cannot finish counting.', 403);
    if (!p.take_id) return bad('Choose a stock-take.');
    return ok('flow_stocktake_review', { p_take: p.take_id, p_actor: actor }, 'Counting finished.');
  case 'stocktake_recount':
    if (!floor) return bad('Your role cannot enter recounts.', 403);
    if (!p.take_id || !s(p.sku)) return bad('Choose a stock-take and a SKU.');
    return ok('flow_stocktake_recount', { p_take: p.take_id, p_sku: s(p.sku), p_qty: p.qty == null || p.qty === '' ? null : Number(p.qty), p_actor: actor }, 'Recount saved.');
  case 'stocktake_accept':
    if (!floor) return bad('Your role cannot accept stock differences.', 403);
    if (!p.line_id) return bad('Choose a line.');
    return ok('flow_stocktake_accept', { p_line: p.line_id, p_reason: s(p.reason), p_senior: senior, p_actor: actor }, 'Difference accepted.');
  case 'stocktake_accept_small':
    if (!floor) return bad('Your role cannot accept stock differences.', 403);
    if (!p.take_id) return bad('Choose a stock-take.');
    return ok('flow_stocktake_accept_small', { p_take: p.take_id, p_reason: s(p.reason), p_actor: actor }, 'Small differences accepted.');
  case 'stocktake_close':
    if (!senior) return bad('Only a manager or admin can close a stock-take.', 403);
    if (!p.take_id) return bad('Choose a stock-take.');
    return ok('flow_stocktake_close', { p_take: p.take_id, p_note: s(p.note) || null, p_actor: actor }, 'Stock-take closed.');
  case 'stocktake_cancel':
    if (!senior) return bad('Only a manager or admin can cancel a stock-take.', 403);
    if (!p.take_id) return bad('Choose a stock-take.');
    return ok('flow_stocktake_cancel', { p_take: p.take_id, p_reason: s(p.reason), p_actor: actor }, 'Stock-take cancelled.');
  case 'stocktake_adjusted':
    if (!floor) return bad('Your role cannot mark a stock-take as corrected.', 403);
    if (!p.take_id) return bad('Choose a stock-take.');
    return ok('flow_stocktake_mark_adjusted', { p_take: p.take_id, p_note: s(p.note) || null, p_actor: actor }, 'Marked as corrected.');
  default:
    return bad('Unknown action.');
}
